import{esc,button,input,range,select}from'../phase4/ui.js';
import{number,mulDigits,multiplier,mulCurrent,divDigits,divCurrent,requiredTests,foundFactors,leaves,isPrime,codeOptions}from'./b14-model.js';
const f=(key,label,value)=>input(key,label,value,'autocomplete="off" spellcheck="false"');
const unit=i=>i>=0?['一','十','百','千','万','十万','百万'][i]||`10的${i}次方`:['十分之一','百分之一','千分之一','万分之一','十万分之一','百万分之一'][-i-1];
const selectNumber=(m,n)=>button('b14-select',String(n),`data-value="${n}" aria-pressed="${m.board.selected.includes(n)}"`);
const squares=(n,cls='')=>`<div class="b14-square ${cls}" style="--side:${Math.max(1,n)}" role="img" aria-label="边长${n}，${n*n}格">${Array.from({length:n*n},()=>'<i></i>').join('')}</div>`;
function writtenRow(n,width,cls=''){return `<div class="b14-written-row ${cls}">${String(n).padStart(width,' ').split('').map(c=>`<span>${c===' '?'':c}</span>`).join('')}</div>`;}
function area(t,m){const b=m.board,x=Math.min(t.a,number(m.cutA)||t.a),y=Math.min(t.b,number(m.cutB)||t.b),committed=b.cuts&&x===b.cuts[0]&&y===b.cuts[1];return `<p class="b14-title">${t.a} × ${t.b}</p><div class="b14-area" style="grid-template-columns:${x}fr ${t.a-x}fr;grid-template-rows:${y}fr ${t.b-y}fr" role="img" aria-label="${t.a}乘${t.b}的面积拆分">${[x,t.a-x].flatMap((r,i)=>[y,t.b-y].flatMap((c,j)=>r&&c?[`<div style="grid-column:${i+1};grid-row:${j+1}"><span>${r} × ${c}</span>${committed?`<b>${b.values[b.parts.findIndex(p=>p.side[0]===i&&p.side[1]===j)]??'?'}</b>`:''}</div>`]:[])).join('')}</div>${t.a===40&&t.b===60?'<p>边上每一捆是10；一捆乘一捆，就是10×10的一百格。</p>':''}`;}
function multiply(t,m){const b=m.board,c=mulCurrent(t,b),w=String(t.a*t.b).length+1;return `<div class="b14-multiply"><div class="b14-written" style="--digits:${w}">${writtenRow(t.a,w)}${writtenRow('×'+t.b,w,'line')}${b.rows.map(r=>writtenRow(r.value,w)).join('')}${b.row<multiplier(t).length?`<div class="b14-written-row working">${String(b.carry||'').padStart(Math.max(0,w-b.digits.length),' ').split('').map(c=>`<span>${c}</span>`).join('')}${[...b.digits].reverse().map(d=>`<span>${d}</span>`).join('')}</div>`:''}</div><div class="b14-column">${!b.estimateOK?`<p>先把 ${t.a} 看成 ${t.estimate}，估一估 ${t.estimate} × ${t.b}。</p>`:b.row>=multiplier(t).length?'<p>两行的单位已经放好。把留下的部分合起来。</p>':b.col>=mulDigits(t).length?`<p>这一行算的是 ${t.a} × ${multiplier(t)[b.row]}${b.row?'个十':'个一'}。送出的最后 ${b.carry} 捆也要留下。</p>`:`<p>这一位：<b>${c.a} 个${unit(b.col)}</b>，取 <b>${c.b} 份</b>，再加送来的 <b>${c.carry} 个${unit(b.col)}</b>。</p>${b.pending?`<div class="b14-counters" aria-label="${b.pending.loose}个${unit(b.col)}，${b.pending.bundles}个${unit(b.col+1)}"><div>${Array.from({length:b.pending.bundles},()=>'<b class="b14-bundle">10</b>').join('')}</div><div>${Array.from({length:b.pending.loose},()=>'<i>1</i>').join('')}</div></div><p>换出 ${b.pending.bundles} 捆，留下 ${b.pending.loose} 个。</p>`:''}`}</div></div>${b.work.length?`<details><summary>看看刚才的换捆</summary><ol>${b.work.map(s=>`<li>第${s.row+1}行，${unit(s.col)}：${s.raw} = ${s.bundles}×10 + ${s.loose}</li>`).join('')}</ol></details>`:''}`;}
function divide(t,m){const b=m.board,ready=b.steps.length===divDigits(t).length,c=divCurrent(t,b),pos=String(t.n).length-1-b.steps.length;return `<p class="b14-title">${t.n} ÷ ${t.d}</p>${b.method?`<div class="b14-division ${b.method}"><div class="b14-quotient">${b.steps.map((s,i)=>`<span>${i===String(t.n).length?'<b>·</b>':''}${s.q}</span>`).join('')||'从左边开始'}</div>${b.method==='long'?`<ol>${b.steps.map((s,i)=>`<li><span>${s.current} 个${unit(String(t.n).length-1-i)}</span><b>分 ${s.q} 份</b><span>拿走 ${s.used}，剩 ${s.r}</span></li>`).join('')}</ol>`:`<div class="b14-short-record">${b.steps.map((s,i)=>`<span>${unit(String(t.n).length-1-i)}：分${s.q}，余${s.r}</span>`).join('')}</div>`}</div>`:''}${!ready&&b.method?`<div class="b14-bring">${b.steps.length?`<span>上一步剩 ${c.previous} 个${unit(pos+1)}</span><b>↓ 换成 ${c.previous*10} 个${unit(pos)}</b><span>再带下 ${c.next} 个${unit(pos)}</span>`:`<span>先取最左边 ${c.next} 个${unit(pos)}</span>`}${b.ready?`<strong>现在有 ${b.current} 个${unit(pos)}，每 ${t.d} 个分一份。</strong>`:''}</div>`:''}${ready&&['up','down'].includes(t.interpret)?`<div class="b14-containers">${Array.from({length:b.containers},(_,i)=>`<div><b>${Math.min(t.d,Math.max(0,t.n-i*t.d))}/${t.d}</b><i style="--fill:${Math.min(1,Math.max(0,(t.n-i*t.d)/t.d))}"></i></div>`).join('')||'<p>先添一份，看看能装下多少。</p>'}</div><p>已放 ${b.containers} 份；可放 ${b.containers*t.d}，原来 ${t.n}。${t.interpret==='up'?`还没安排 ${Math.max(0,t.n-b.containers*t.d)}`:`完整装入后剩 ${t.n-b.containers*t.d}`}</p>`:''}`;}
function search(t,m){const b=m.board;if(t.mode==='recallPrimes')return `<div class="b14-number-grid">${Array.from({length:t.ns[0]},(_,i)=>selectNumber(m,i+1)).join('')}</div>`;
 if(['multiples','squares'].includes(t.mode))return `<div class="b14-search-lanes">${t.ns.map((n,i)=>`<section><b>${t.mode==='squares'?'边长乘自己':`每次 +${n}`}</b><div class="b14-hops">${b.lists[i].map((v,j)=>`<span>${t.mode==='squares'?`${j+1}² = `:''}${v}</span>`).join('')}</div>${button('b14-list','接上下一块',`data-side="${i}"`)}</section>`).join('')}</div>${t.ns.length===2?`<p>选择最先相遇的 ${t.count} 个正数。</p><div class="b14-number-grid">${[...new Set(b.lists.flat())].sort((a,b)=>a-b).map(n=>selectNumber(m,n)).join('')}</div>`:''}`;
 return `<div class="b14-search-lanes">${t.ns.map((n,i)=>`<section><b>${n} 的查找桌</b><p>这次检查：${requiredTests(t,i).join('、')}</p><div class="b14-tests">${b.tests[i].map(s=>`<span>${n} ÷ ${s.d}，余 ${s.r}${s.r===0?' ✓':''}</span>`).join('')}</div><p>已经找到：${foundFactors(t,b,i).join('、')||'还没有'}</p>${button('b14-test',`试着分 ${n}`,`data-side="${i}"`)}</section>`).join('')}</div>${t.mode==='commonFactors'?`<p>点选两边共同的伙伴。</p><div class="b14-number-grid">${[...new Set(t.ns.flatMap((_,i)=>foundFactors(t,b,i)))].sort((a,b)=>a-b).map(n=>selectNumber(m,n)).join('')}</div>`:''}`;}
function pairs(n){const count=Math.floor(n/2);return `<div class="b14-pairs">${count<=8?Array.from({length:count},()=>'<span>● ●</span>').join(''):`<span class="b14-many">${count} 对，每对 ● ●</span>`}${n%2?'<em>●</em>':''}</div>`;}
function parity(t,m){const b=m.board;if(!b.first)return `<p class="b14-title">${t.a} ${t.op} ${t.b}</p><p>先不求总数，猜一猜能不能全部两两配好。</p>`;return t.op==='+'?`<div class="b14-pair-lanes"><section><b>${t.a} 个</b>${pairs(t.a)}</section><section><b>${t.b} 个</b>${pairs(t.b)}</section></div>${b.joined?`<div class="b14-joined">原来配好的 ${Math.floor(t.a/2)+Math.floor(t.b/2)} 对仍在。${t.a%2&&t.b%2?'<span>两个落单的 → <b>● ●</b> 新的一对</span>':(t.a+t.b)%2?'<span>仍有一个落单的 ●</span>':'<span>两边都没有落单的。</span>'}</div>`:''}`:`<div class="b14-whole-pairs">${Array.from({length:b.joined?t.a/2:t.a},()=>`<section><span>${t.b} 个</span>${b.joined?`<b>↔</b><span>${t.b} 个</span>`:''}</section>`).join('')}</div><p>${b.joined?'两份中的物品按相同位置一一作伴。没有剩下一份。':'把同样大小的整份两两放在一起。'}</p>`;}
function tree(t,m){const b=m.board,matched=b.matches.flat(),renderNode=id=>{const n=b.nodes[id];return `<li><div>${n.children.length?`<span>${n.value}</span>`:button('b14-leaf',String(n.value),`data-index="${id}" class="${isPrime(n.value)?'prime':''}" aria-pressed="${b.selected===id}"`)}${t.common&&!n.children.length&&isPrime(n.value)?button('b14-match',matched.includes(id)?'已配好':b.pair.includes(id)?'等另一边':'配伙伴',`data-index="${id}" ${matched.includes(id)?'disabled':''}`):''}</div>${n.children.length?`<ul>${n.children.map(renderNode).join('')}</ul>`:''}</li>`;};return `${b.first?`<p class="b14-record">第一种已留下：${esc(b.first.expression)}。现在换第一刀。</p>`:''}<div class="b14-forests">${t.ns.map((n,i)=>`<section><b>${n}</b><ul class="b14-tree">${renderNode(i)}</ul></section>`).join('')}</div>${t.common?`<div class="b14-matches">${b.matches.map(p=>`<span>${b.nodes[p[0]].value} ↔ ${b.nodes[p[1]].value}</span>`).join('')||'还没有配成的伙伴。'}</div>`:''}`;}
function plan(t,m){const b=m.board;return `<div class="b14-plan">${b.groups.map((g,i)=>`<section>${button('b14-plan-pick',String(g.value),`data-index="${i}" aria-pressed="${b.selected.includes(i)}" ${t.split&&!b.split||b.groups.length===1?'disabled':''}`)}<small>${g.ids.length===1?(typeof g.ids[0]==='number'?esc(t.labels[g.ids[0]]):'从24拆出的部分'):'刚才合出的这张'}</small></section>`).join('')}</div><ol>${b.merges.map(x=>`<li>${x.left} ${x.op==='*'?'×':'÷'} ${x.right} = ${x.value}</li>`).join('')}</ol>${t.money?'<p>卡片上的价钱用“分”算；最后换成“元”写答案。</p>':''}`;}
function code(t,m){const b=m.board,r=b.runs.at(-1);return `<div class="b14-code-pool">${[2,0,4,1,3].map(i=>codeOptions(t.mode)[i]).map(([value,label])=>button('b14-block',label,`data-value="${value}"`)).join('')}</div><ol class="b14-code-order">${b.blocks.map(k=>`<li>${codeOptions(t.mode).find(x=>x[0]===k)[1]}</li>`).join('')||'<li>点上面的句子，按先后摆在这里。</li>'}</ol>${r?`<p>这次留下：<b>${r.output.join('、')||'没有'}</b></p><details open><summary>逐个检查的记录</summary><div class="b14-code-trace">${r.trace.map(x=>`<span class="${x.keep?'kept':''}">${x.n}：${t.mode==='factors'?`余${x.r}`:`因数${x.factors.join('、')}（${x.count}个）`}${x.keep?' → 留下':''}</span>`).join('')}</div></details>`:''}`;}
function sheet(t,m){const b=m.board;return `<div class="b14-sheet"><div><b>格子</b><b>数</b><b>这一格的规则</b></div>${Array.from({length:t.rows},(_,i)=>`<div><span>A${i+1}</span>${b.values.length?button('b14-select',String(b.values[i]),`data-value="${i}" aria-pressed="${b.selected.includes(i)}" ${!t.highlight?'disabled':''}`):'<span>?</span>'}<span>${b.values.length?(i?`=A${i}+${t.step}`:'第一份'):''}</span></div>`).join('')}</div>${t.highlight?`<p>表格出来后，点选还能被 ${t.highlight} 整除的数。</p>`:''}`;}
export function visual(t,m){switch(t.type){case'x-areaproduct':return area(t,m);case'x-multable':return multiply(t,m);case'x-divtable':return divide(t,m);case'x-numbersearch':return search(t,m);case'x-parityjoin':return parity(t,m);case'x-factorforest':return tree(t,m);case'x-planproduct':return plan(t,m);case'x-squarepair':{const x=Math.min(10,number(m.sideA)||0),y=Math.min(10,number(m.sideB)||0);return `<div class="b14-square-pair">${squares(x)}<b>+</b>${squares(y,'other')}</div><p>${x}×${x} + ${y}×${y} = ${x*x+y*y}，目标 ${t.total}</p>`;}case'x-factorcode':return code(t,m);case'x-multisheet':return sheet(t,m);}return'';}
const parityChoices=[['even','能全部配好'],['odd','会剩一个']];
export function controls(t,m){const b=m.board;switch(t.type){
 case'x-areaproduct':return f('cutA',`${t.a}这条边，第一段多长`,m.cutA)+f('cutB',`${t.b}这条边，第一段多长`,m.cutB)+button('b14-cut','按这里分开')+(b.cuts&&b.values.length<b.parts.length?f('part',`第${b.values.length+1}块有多少格`,m.part)+button('b14-part','留下这一块'):'')+(b.cuts&&b.values.length===b.parts.length?(t.a===40&&t.b===60?f('base','4捆十乘6捆十，共几个百',m.base):'')+f('answer','合起来一共有多少',m.answer):'');
 case'x-multable':if(!b.estimateOK)return f('estimate',`先估 ${t.estimate}×${t.b} 大约多少`,m.estimate)+button('b14-estimate','留下估计，开始算');else if(b.row===multiplier(t).length)return f('answer','把各行合起来，精确结果是多少',m.answer);else if(b.col===mulDigits(t).length)return select('shift','这一行往高位挪几格',m.shift,[['0','不挪，乘的是几份一'],['1','挪一格，乘的是几份十']])+f('rowvalue','这一整行表示多少',m.rowvalue)+button('b14-row','把这一行放好');else if(!b.pending)return f('raw','相乘再加送来的，一共几个当前单位',m.raw)+button('b14-mul-count','摆出这些数量');else return button('b14-trade','十个换成一捆',b.pending.loose<10?'disabled':'')+f('digit','换完后，这一位留下哪个数字',m.digit)+button('b14-digit','留下这一位，往前走');
 case'x-divtable':if(!b.method)return select('method','哪种记法方便自己检查',m.method,[['short','紧凑地记每位'],['long','展开每次乘和减']])+button('b14-method','就用这种');else if(b.steps.length<divDigits(t).length)return b.ready?f('q','这一段能分几份（0到9）',m.q)+f('used','乘回去，一共拿走多少',m.used)+f('rest','这一段还剩多少',m.rest)+button('b14-div-step','留下这一位'):button('b14-bring',b.steps.length?'把剩下的换小，再带下下一位':'取最左边这一位');else return f('check','把整数商×每份+余数写成等式，倒着检查',m.check)+(['up','down'].includes(t.interpret)?button('b14-container','添一份','data-value="1"')+button('b14-container','收回一份',`data-value="-1" ${b.containers===0?'disabled':''}`):'')+(t.choosePrecision?select('precision','价钱写到哪里',m.precision,[['0','元'],['1','角（1位小数）'],['2','分（2位小数）']]):'')+f('answer',t.interpret==='keep'?'整数商是多少':t.interpret==='fraction'?'每份多少（如 15 5/8）':t.interpret==='round'?`按问题写近似结果，保留${t.dp}位小数`:'按故事，最后答案是多少',m.answer)+(t.interpret==='keep'?f('base','原来这些量，还剩多少',m.base):'');
 case'x-numbersearch':if(t.mode==='recallPrimes')return'<p>选好了就检查这一小步。</p>';else if(['multiples','squares'].includes(t.mode))return f('answer',t.mode==='squares'?'下一块有多少格':'下一块是多少',m.answer);else return f('candidate','这次用几去分',m.candidate)+f('remainder','还剩多少',m.remainder)+(t.mode==='prime'?select('answer','查完后，你的判断',m.answer,[['prime','质数：恰好两个不同因数'],['composite','合数：不止两个因数'],['neither','两个都不是']]):t.mode==='divisible'?select('answer',`能被${t.by}整除吗`,m.answer,[['yes','能'],['no','不能']]):'');
 case'x-parityjoin':return !b.first?select('prediction','先猜一猜',m.prediction,parityChoices)+button('b14-predict','留下猜想，展开看'):!b.joined?button('b14-join',t.op==='+'?'把落单的放在一起':'把整份两两作伴'):select('answer','配完之后',m.answer,parityChoices)+select('reason','为什么',m.reason,[['two','两颗落单的又成了一对'],['one','只有一颗落单的，没有伙伴'],['none','两边原本就都配好了'],['whole','相同的整份两两作伴，每个位置都能配上']]);
 case'x-factorforest':return (b.selected!==null?`<p>把 ${b.nodes[b.selected].value} 拆成两块。</p>`+f('left','一块是多少',m.left)+f('right','另一块是多少',m.right)+button('b14-split','拆开这块'):'<p>点一块还可以拆的数。</p>')+f('expression',`${t.ns[0]}最后由哪些质数相乘（可用 ^ 写幂）`,m.expression)+(t.twice&&!b.first?button('b14-tree-save','留下这一棵，换个第一刀'):'')+(t.common?f('equation',`${t.ns[1]}由哪些质数相乘`,m.equation)+f('hcf','共有的全部质数块相乘（没有时填1）',m.hcf)+f('lcm','保留足够两边各自使用的份数，相乘是多少',m.lcm):'');
 case'x-planproduct':return t.split&&!b.split?f('left','把24拆成：一块',m.left)+f('right','另一块',m.right)+button('b14-plan-split','用两块换掉24'):b.groups.length>1?(!t.split?select('operator','按点选先后，怎么合这两张',m.operator,[['*','相乘'],['/','前一张除以后面的']]):'')+f('result','选中的这两张算出多少',m.result)+button('b14-merge','先合这两张',b.selected.length!==2?'disabled':'')+(b.merges.length?button('b14-undo','退一步换搭档'):''):f('answer',t.money?'一共多少元（保留两位小数）':'最后是多少',m.answer)+(t.equations?f('equation','用n表示答案，写出与故事对应的关系',m.equation):'')+button('b14-undo','退一步换搭档');
 case'x-squarepair':return range('sideA','第一块边长',m.sideA,0,10)+range('sideB','第二块边长',m.sideB,0,10)+button('b14-square','用这两块拼一拼');
 case'x-factorcode':return button('b14-block-undo','拿回最后一句',!b.blocks.length?'disabled':'')+select('condition','怎样的数留下',m.condition,t.mode==='factors'?[['zero','余数是0'],['nonzero','余数不是0']]:[['two','恰好2个不同因数'],['one','只有1个因数'],['more','多于2个因数']])+button('b14-run','照这个办法运行');
 case'x-multisheet':return f('start','A1：第一格放多少',m.start)+f('formula','A2：引用A1，怎样接出下一份（先写=）',m.formula)+button('b14-sheet','把规则延续到下面');
}return'';}
export const render=(t,m)=>`<section class="b14-work"><div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}${m.issue?`<p class="b14-issue" role="status">${esc(m.issue)}</p>`:''}${button('b14-reset','重新做，保留之前的尝试')}</div></section>`;
